    "title": "Constituição do Pará (CEPA/1989) - Artigo 176",
    "content": "Compete ao Estado do Pará instituir impostos sobre transmissão causa mortis e doação (ITCD), circulação de mercadorias e serviços (ICMS) e propriedade de veículos automotores (IPVA), além de arrecadar a compensação financeira pela exploração de recursos minerais e hídricos.",
